---@class Page_OtherStyleView
Page_OtherStyleView = class("Page_OtherStyleView")

function Page_OtherStyleView:initialize(parentPref)
    self.parentPref = parentPref
    self.ScrollView = UIUtil.GetTypeChildWightInputPath("ScrollView", self.parentPref, typeof(MoreRowScrollView))
    self.ScrollRect = UIUtil.GetTypeChildWightInputPath("ScrollView", self.parentPref, typeof(ScrollRect))
    CommonHelper:HButtonSetCallback("Close",self.parentPref,function (hbtn)
        UIManager:Get():ClosePopup()
    end)
    self.unLoopBgRect=UIUtil.GetTypeChildWightInputPath("unLoopBg",self.parentPref,typeof(RectTransform))
end

function Page_OtherStyleView:SetData(title,des)
    CommonHelper:SetText("###title2", self.parentPref, title)
    --CommonHelper:SetText("desc", self.gameObject, des)
    local strList = stringSplit(des,"|")
    local littleTitleList = stringSplit(strList[1],":")
    CommonHelper:SetText("###littletitle1", self.parentPref, littleTitleList[1] and littleTitleList[1] or "")
    CommonHelper:SetText("###littletitle2", self.parentPref, littleTitleList[2] and littleTitleList[2] or "")
    CommonHelper:SetText("###littletitle3", self.parentPref, littleTitleList[3] and littleTitleList[3] or "")
    CommonHelper:SetText("###littletitle4", self.parentPref, littleTitleList[4] and littleTitleList[4] or "")
    local KV = stringSplit(strList[2],":")
    local count=math.modf(#KV/2)
    CommonHelper:InitMoreRowScrollView( self.ScrollView,count,1,function(index,item,scrollview)
        CommonHelper:SetNewLineText("###Key",item,KV[index*2+1])
        CommonHelper:SetNewLineText("###Value",item,KV[(index+1)*2])
    end)
    CommonHelper:ScrollViewEnableDrag(self.ScrollRect,false,count>4)
    CommonHelper:SetGameObjectActive("loopBg",self.parentPref,count>4)
    CommonHelper:SetGameObjectActive("unLoopBg",self.parentPref,count<5)
    if count<5 then
        CommonHelper:SetRectSizeDeltaByName("unLoopBg",self.parentPref, 918, count*80+76)
    end
end